 "content": "def transform(grid):
    # Each outlined rectangle is a frame. Fill its interior with the color
    # of the frame, except objects already drawn inside remain as pattern.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == 9 or (r, c) in seen:
                continue
            # Connected components of each non-background color; frame outlines
            # enclose a rectangular area with sides all in the same color.
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop(); comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            # Identify rectangular frames from bounding box and fill the hole.
            r0=min(y for y,x in comp); r1=max(y for y,x in comp)
            c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                       if y in (r0,r1) or x in (c0,c1)}
            if all(g[y][x] == color for y,x in perimeter):
                # only fill formerly empty/background cells within that frame
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        if g[y][x] == 9:
                            g[y][x] = color
    # Some frames share color, so components can merge; use direct rectangle
    # detection from rows/columns as well, to support the full task instances.
    return g
