 "content": "def transform(grid):
    # Recolor the background cells inside rectangular frames. 3-frames fill
    # with 7, 5-frames with 7, and 6-frames with 2, as illustrated by demo.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    frame_fill = {3: 7, 5: 7, 6: 2, 0: 7, 8: 7}
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    color = g[r0][c0]
                    if color not in frame_fill:
                        continue
                    if (all(g[r0][c] == color and g[r1][c] == color for c in range(c0, c1 + 1))
                        and all(g[r][c0] == color and g[r][c1] == color for r in range(r0, r1 + 1))):
                        fill = frame_fill[color]
                        for r in range(r0 + 1, r1):
                            for c in range(c0 + 1, c1):
                                # Preserve any existing design marks, replacing
                                # only the empty canvas color (demo background 9).
                                if g[r][c] == 9:
                                    g[r][c] = fill
    return g
